{"content": "import 'package:flutter/material.dart';

/// Сообщает о потере фокуса вложенным виджетам.
///
/// Фокус теряется, когда пользователь уходит с экрана: переключает вкладку,
/// открывает другой маршрут или диалог.
class FocusLossDetector extends StatefulWidget {
  const FocusLossDetector({
    super.key,
    required this.onFocusLost,
    required this.child,
  });

  final VoidCallback onFocusLost;

  final Widget child;

  @override
  State<FocusLossDetector> createState() => _FocusLossDetectorState();
}

class _FocusLossDetectorState extends State<FocusLossDetector> {
  late final FocusNode _focusNode;

  /// Фокус был получен хотя бы раз: до этого терять нечего.
  bool _hadFocus = false;

  @override
  void initState() {
    super.initState();

    _focusNode = FocusNode(debugLabel: 'FocusLossDetector')..addListener(_onFocusChanged);

    WidgetsBinding.instance.addPostFrameCallback((_) => _requestFocus());
  }

  @override
  void dispose() {
    _focusNode
      ..removeListener(_onFocusChanged)
      ..dispose();

    super.dispose();
  }

  void _requestFocus() {
    if (!mounted) return;

    // Явно поднимаем фокус до корневой области: так экран получает фокус
    // независимо от того, есть ли на нём активное поле ввода.
    FocusManager.instance.rootScope.requestFocus();
    _focusNode.requestFocus();

    _hadFocus = _focusNode.hasFocus;
  }

  void _onFocusChanged() {
    if (_focusNode.hasFocus) {
      _hadFocus = true;

      return;
    }

    if (!_hadFocus) return;

    _hadFocus = false;
    widget.onFocusLost();
  }

  @override
  Widget build(BuildContext context) {
    return Focus(
      focusNode: _focusNode,
      canRequestFocus: false,
      child: widget.child,
    );
  }
}
